// AliasTest
// ---------------------------------------------------------------------------------

/// One registered `AliasTest`. The generator emits one of these per manifest entry;
/// upstream's `CaseDef` strings live in the shader the entry points at, so all that is
/// left here is what `checkSupport` reads.
#[derive(Clone, Copy)]
pub struct AliasCase {
    pub name: &'static str,
    pub layout: LayoutFlags,
    pub requirements: u32,
    pub programs: BinaryCollection,
}

impl TestCase for AliasCase {
    fn name(&self) -> &str {
        self.name
    }

    /// `AliasTest::checkSupport`
    fn check_support(&self, context: &Context<'_>) -> Result<(), TestError> {
        let p = CheckSupportParams {
            needs_scalar: self.layout == LayoutFlags::Scalar,
            needs_int8: (self.requirements & REQUIREMENT_INT8) != 0,
            needs_int16: (self.requirements & REQUIREMENT_INT16) != 0,
            needs_int64: (self.requirements & REQUIREMENT_INT64) != 0,
            needs_float16: (self.requirements & REQUIREMENT_FLOAT16) != 0,
            needs_float64: (self.requirements & REQUIREMENT_FLOAT64) != 0,
            compute_pipeline_construction_type: CONSTRUCTION_TYPE,
        };

        check_support_with_params(context, &p)
    }

    /// `AliasTest::initPrograms`, resolved ahead of time by the manifest.
    fn programs(&self) -> BinaryCollection {
        self.programs
    }

    fn create_instance<'a>(&'a self, context: &'a Context<'a>) -> Box<dyn TestInstance + 'a> {
        Box::new(AliasInstance {
            context,
            compute_pipeline_construction_type: CONSTRUCTION_TYPE,
        })
    }
}

/// `AliasTest::Instance`
struct AliasInstance<'a> {
    context: &'a Context<'a>,
    compute_pipeline_construction_type: ComputePipelineConstructionType,
}

impl TestInstance for AliasInstance<'_> {
    /// `AliasTest::Instance::queuePass`, run once on the universal queue.
    fn iterate(&mut self) -> TestOutcome {
        run_compute(
            self.context,
            1,
            self.compute_pipeline_construction_type,
            self.context.get_universal_queue(),
            self.context.get_universal_queue_family_index(),
        )
    }
}

